import React from 'react';

const ChatMessage = ({ sender, text }) => {
  const isUser = sender === 'user';
  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`whitespace-pre-wrap max-w-[80%] px-4 py-2 rounded-xl text-sm shadow ${isUser ? 'bg-green-200 text-right text-gray-800' : 'bg-gray-200 text-left text-gray-900 dark:bg-gray-700 dark:text-gray-100'}`}>
        {text}
      </div>
    </div>
  );
};

export default ChatMessage;
